"tw.local.isChecker = false;
if(tw.local.isFirstTime == true)
{
	tw.local.odcRequest.appInfo.initiator = tw.system.user.fullName+"( "+ tw.system.user.name+")";
//	tw.local.odcRequest.appInfo.requestName = "ODC collection";
	tw.local.odcRequest.appInfo.requestName = tw.epv.ProcessNames.odcCollection;
	tw.local.odcRequest.appInfo.requestType = tw.local.odcRequest.requestType.name;
	tw.local.odcRequest.appInfo.status ="Initiated";
	tw.local.odcRequest.appInfo.subStatus ="Initiated";
	tw.local.odcRequest.appInfo.stepName =tw.epv.Col_ScreenNames.ODCCol01;
	tw.local.odcRequest.appInfo.instanceID = tw.local.odcRequest.requestNo; 
}

//---------------------------------Init Step log ---------------------------------------------------	 	 
tw.local.odcRequest.stepLog={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step = tw.epv.Col_ScreenNames.ODCCol01; 

 //----------------------------------------------------------------------------------------------
//Init actionConditions "This object used by service (Get Actions by ScreenName 2) "
tw.local.actionConditions={};
tw.local.actionConditions.complianceApproval= false;
tw.local.actionConditions.lastStepAction= tw.local.odcRequest.stepLog.action;
tw.local.actionConditions.screenName= tw.epv.Col_ScreenNames.ODCCol01;
tw.local.actionConditions.userRole= tw.local.odcRequest.initiator;
tw.local.actionConditions.subStatus= tw.local.odcRequest.appInfo.subStatus;	 
tw.local.actionConditions.isLiquidated= tw.local.odcRequest.isLiquidated;	

//Init liquidation data
tw.local.odcRequest.ContractLiquidation.liqCurrency= tw.local.odcRequest.FinancialDetailsBR.currency.value;
//init request state 
tw.local.odcRequest.BasicDetails.requestState="undergoing collection";

if(tw.local.odcRequest.isLiquidated == false)	{
	tw.local.odcRequest.ContractLiquidation= {};
	tw.local.odcRequest.ContractLiquidation.creditedAccount= {};
	tw.local.odcRequest.ContractLiquidation.creditedAmount= {};
	tw.local.odcRequest.ContractLiquidation.creditedAccount.currency={};
	}
	
tw.local.odcRequest.BasicDetails.requestNature = tw.local.odcRequest.requestNature.name;
tw.local.odcRequest.BasicDetails.requestType = 	tw.local.odcRequest.requestType.name;

tw.local.odcRequest.ContractLiquidation.creditedAccount = {};
tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass={};
tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.name= "Customer Account";
tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value= "Customer Account";

//Set Liq Currency with request currency 
tw.local.odcRequest.ContractLiquidation.liqCurrency= tw.local.odcRequest.FinancialDetailsBR.currency.name;"]}},{"outgoing":["2027.636dd5a7-5fa4-479c-8391-90dea46b8d50"],"incoming":["2027.4c92b8b9-010a-45a8-8d5b-0ba165ad5df3"],"eventDefinition":[{"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TPostponeTaskEventDefinition"}],"extensionElements":{"default":["2027.636dd5a7-5fa4-479c-8391-90dea46b8d50"],"nodeVisualInfo":[{"width":24,"x":803,"y":298,"declaredType":"TNodeVisualInfo","height":24}],"navigationInstructions":[{"targetType":"Default","declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TNavigationInstructions"}]},"name":"Postpone","declaredType":"intermediateThrowEvent","id":"2025.d0e44a57-c5bc-441e-8b1f-62fcdc4850e5"},{"targetRef":"2025.2cd1e05e-e819-41b6-8d95-dfb27dd0b710","extensionElements":{"coachEventBinding":[{"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TCoachEventBinding","id":"42dd92fa-be2a-4d01-8ae0-3aec571876c7","coachEventPath":"DC_Templete1/submit"}],"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":false,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":true,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To End","declaredType":"sequenceFlow","id":"2027.8ebe87c1-8533-4f25-83cb-24907c146d75","sourceRef":"2025.a54f759f-5a8e-4534-9b01-e72fbb495a0c"},{"startQuantity":1,"outgoing":["2027.da9e7e56-6c63-403a-8135-0f9c7f1c5c25"],"incoming":["2027.8ebe87c1-8533-4f25-83cb-24907c146d75"],"default":"2027.da9e7e56-6c63-403a-8135-0f9c7f1c5c25","extensionElements":{"postAssignmentScript":[],"nodeVisualInfo":[{"color":"#95D087","width":95,"x":936,"y":179,"declaredType":"TNodeVisualInfo","height":70}],"preAssignmentScript":[]},"name":"Validation","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.2cd1e05e-e819-41b6-8d95-dfb27dd0b710","scriptFormat":"text/x-javascript","script":{"content":["tw.local.errorMessage = "";
var mandatoryTriggered = false;
var validateDec14 = " accepts 14 digits before the decimal point and 2 digits after it.";
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/

//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");

if (tw.local.odcRequest.stepLog.action == tw.epv.Col_Actions.cancel) {
	mandatory(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment");
}

if (tw.local.odcRequest.stepLog.action == tw.epv.Col_Actions.createLiq) {
	validateLiq();
}

//------------------------------------------------- Contract Liquidation VALIDATION -----------------------------------------
function validateLiq() {
	//debugger;
	mandatory(tw.local.odcRequest.ContractLiquidation.liqAmount, "tw.local.odcRequest.ContractLiquidation.liqAmount");

	//Dates
	mandatory(tw.local.odcRequest.ContractLiquidation.creditValueDate, "tw.local.odcRequest.ContractLiquidation.creditValueDate");
	mandatory(tw.local.odcRequest.ContractLiquidation.debitValueDate, "tw.local.odcRequest.ContractLiquidation.debitValueDate");

	// to be back after UAT.
	// notPastDate(tw.local.odcRequest.ContractLiquidation.creditValueDate, "tw.local.odcRequest.ContractLiquidation.creditValueDate", "Credit Value Date cannot be less than request date","Credit Value Date cannot be less than request date",false);
	// notPastDate(tw.local.odcRequest.ContractLiquidation.debitValueDate, "tw.local.odcRequest.ContractLiquidation.debitValueDate", "Debit Value Date cannot be less than request date","Debit Value Date cannot be less than request date",false);

	mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value, "tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass");

	//Validate Nestro Account
	if (tw.local.odcRequest.ContractLiquidation.verifyDebitAccountNoMsg == "" || tw.local.odcRequest.ContractLiquidation.verifyDebitAccountNoMsg == null) {
		addError("tw.local.odcRequest.ContractLiquidation.debitedAccountNo", "Nestro Account is not verified", "Nestro Account is not verified");
	}
	mandatory(tw.local.odcRequest.ContractLiquidation.debitedAccountNo, "tw.local.odcRequest.ContractLiquidation.debitedAccountNo");

	if (tw.local.odcRequest.ContractLiquidation.liqAmount > 0) validateDecimal2(tw.local.odcRequest.ContractLiquidation.liqAmount, "tw.local.odcRequest.ContractLiquidation.liqAmount", "Liquidation Amount" + validateDec14);

	if (tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value == "GL Account") {
		mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo, "tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo");

		if (!!tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo && tw.local.odcRequest.ContractLiquidation.isGlVerified == false) {
			// tw.local.errorMessage += "<li>" + "GL Account is not verified." + "</li>";
			addError("tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo", "GL Account is not verified.");
		}
		if (!!tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo) {
			mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.branchCode, "tw.local.odcRequest.ContractLiquidation.creditedAccount.branchCode");
			mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.currency.value, "tw.local.odcRequest.ContractLiquidation.creditedAccount.currency.value");
		}

		//Validate OverDraft
		// if (tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount > tw.local.odcRequest.ContractLiquidation.creditedAccount.balance && tw.local.odcRequest.ContractLiquidation.creditedAccount.isOverDraft) {
		// addError("tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount", "ERROR: Must be <= Account Balance", "ERROR: Must be <= Account Balance")
		// }
	} else {
		mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.customerAccountNo, "tw.local.odcRequest.ContractLiquidation.creditedAccount.customerAccountNo");
	}

	if (tw.local.odcRequest.ContractLiquidation.liqAmount > tw.local.odcRequest.FinancialDetailsFO.outstandingAmount) {
		addError("tw.local.odcRequest.ContractLiquidation.liqAmount", "Liquidation Amount must be <= ODC Outstanding Amount", "Liquidation Amount must be less than or equal to ODC Outstanding Amount.");
		// tw.local.errorMessage += "<li>" + "Liquidation Amount must be less than or equal to ODC Outstanding Amount." + "</li>";
	}
	// if (tw.local.odcRequest.ContractLiquidation.creditedAccount.balance > 0) {
	//		validateDecimal2(tw.local.odcRequest.ContractLiquidation.creditedAccount.balance, "tw.local.odcRequest.ContractLiquidation.creditedAccount.balance", "balance"+validateDec14)
	// }
	// if (tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount > 0) {
	//		validateDecimal2(tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount, "tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount", validateDec14)
	// }

	//----------------------------------------------- Charges and Commissions VALIDATION -------------------------------------
	for (var i = 0; i < tw.local.odcRequest.ChargesAndCommissions.length; i++) {
		//Description - Flat Amount
		var changeAmount = tw.local.odcRequest.ChargesAndCommissions[i].changeAmount;

		if (tw.local.odcRequest.ChargesAndCommissions[i].rateType == "Flat Amount") {
			if (changeAmount < 0 || changeAmount == null || changeAmount == undefined) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Change Amount Must be >= 0", "Change Amount Must be >= 0");
			}

			if (tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {
				validateDecimal2(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Change Amount" + validateDec14);
			}

			//Fixed Rate
		} else {
			var changePercentage = tw.local.odcRequest.ChargesAndCommissions[i].changePercentage;
			if (changePercentage < 0 || changePercentage == null || changePercentage == undefined) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Change Percentage Must be >= 0", "Change Percentage Must be >= 0");
			}

			if (changePercentage > 0 && changePercentage > 100) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Change Percentage Must be <= 100", "Change Percentage Must be <= 100");
			}
		}

		//skip validation if waiver or changeAmnt < 0
		if (tw.local.odcRequest.ChargesAndCommissions[i].waiver == false && tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {
			//GL Account
			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value == "GL Account") {
				if (tw.local.odcRequest.ChargesAndCommissions[i].isGLFound == false) {
					addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo", "GL Account Not Verified", "GL Account Not Verified");
				}

				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo");
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency.value, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.currency");
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.branchCode, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.branchCode");

				//Customer Account
			} else {
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.customerAccountNo");
			}

			//DebitedAmount

			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate > 0) {
				validateDecimal(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.negotiatedExRate", "This field accepts 14 digits before the decimal point and 2 digits after it.");
			}

			//Correct Validation but Waiting confirmation on what to do if GL account
			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.amountInAccount > tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.balance && tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.isOverDraft == false) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.amountInAccount", "ERROR: Debited Amount in account currency Must be <= Account Balance", "ERROR: Debited Amount in account currency Must be <= Account Balance");
			}
		}
	}
	//	validateTab(9, "Charges and commisions Tab");

	//--------------------------------------Multi Tenor----------------------------------------------------------
//--------------------------------------Multi Tenor----------------------------------------------------------
if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates && tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length > 0) {
	var LiqAmnt = tw.local.odcRequest.ContractLiquidation.liqAmount;
	var equalToLiqAmntCount = 0;
	var nonZeroCount = 0;
	var equalToLiqAmntIndex = -1;
	var sumliqamunt =0;
	// Single loop to count conditions
	for (var i = 0; i < tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length; i++) {
		var splitLiqAmnt = tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].liquidationAmnt;
		var splitAmnt = tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount;
		sumliqamunt +=tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].liquidationAmnt;
//		if(splitLiqAmnt > splitAmnt ){
//			addError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates["+i+"].liquidationAmnt", "The liquidation amount must be less than tenor amount");
//		}
		if (splitLiqAmnt > 0) {
			nonZeroCount++;
		}

		if (splitLiqAmnt == LiqAmnt) {
			equalToLiqAmntCount++;
			equalToLiqAmntIndex = i;
		}
	}

	// Add error only to first element based on validation results
	if (nonZeroCount == 0) {
		addError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[0].liquidationAmnt", "At least one Instalment liquidation amount must be greater than zero");
	} else if (equalToLiqAmntCount != 1) {
//		addError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[0].liquidationAmnt", "Exactly one Instalment liquidation amount must equal the total liquidation amount");
	} else if (nonZeroCount > 1) {
//		addError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[0].liquidationAmnt", "When one Instalment liquidation amount equals the total liquidation amount, all other Instalment amounts must be zero");
	} 
	if (sumliqamunt != LiqAmnt ) {

		addError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[0].liquidationAmnt", "The total amount must equal the liquidation amount");
	}
//else if (equalToLiqAmntIndex >= 0) {
//		// Additional validation: check if LiqAmnt equals splitAmnt for the matching instalment
//		var matchingSplitAmnt = tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[equalToLiqAmntIndex].amount;
//		if (LiqAmnt != matchingSplitAmnt) {
//			addError("tw.local.odcRequest.ContractLiquidation.liqAmount", "The total liquidation amount must equal the instalment amount");
//		}
//	}
	
}

} //end of validation function

/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
 * =========================================================================================================
 *
 * Add a coach validation error
 *
 * EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
 *
 * =========================================================================================================
 */
function addError(fieldName, controlMessage, validationMessage, fromMandatory) {
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : (tw.local.errorMessage += "<li>" + validationMessage + "</li>");
}
/*
 * =======================================================================================================================
 *
 * Add a coach validation error if the date1 is less than date2
 *
 * EX:checkDate( date , dateName,'this is a validation message!' , 'this is a validation message!')
 *
 * =======================================================================================================================
 */
function checkDate(date, dateName, controlMessage, validationMessage) {
	debugger;
	var todayDate = new Date();
	if (date != null && date != "" && date != undefined && date < todayDate) {
		addError(dateName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * =================================================================================================================================
 *
 * Add a coach validation error if the string length is less than given length
 *
 * EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =================================================================================================================================
 */

function minLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field != null && field != undefined && field.length < len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * =======================================================================================================================
 *
 * Add a coach validation error if the string length is greater than given length
 *
 * EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
 *
 * =======================================================================================================================
 */
function maxLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field.length > len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * ==================================================================================================================
 *
 * Add a coach validation error if the field is null 'Mandatory'
 *
 * EX:	notNull(tw.local.name , 'tw.local.name')
 *
 * ==================================================================================================================
 */

function mandatory(field, fieldName) {
	if (field == null || field == undefined) {
		addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
		mandatoryTriggered = true;
		return false;
	} else {
		switch (typeof field) {
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0) {
					var msg = "Invalid Value, This field can not be negative value.";
					addError(fieldName, msg, msg, true);
					mandatoryTriggered = true;
					return false;
				}
				break;

			case "boolean":
				if (field == false) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			default:
				// VALIDATE DATE OBJECT
				if (field && field.getTime && isFinite(field.getTime())) {
				} else {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
		}
	}
	return true;
}
// ==================================================================================================================
//Validate Decimal(10,6)
function validateDecimal(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,4}(\.\d{1,6})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, validationMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}

//Validate Decimal(14,2)
function validateDecimal2(field, fieldName, controlMessage, validationMessage) {
	validationMessage = controlMessage;
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,12}(\.\d{1,2})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, validationMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}

//check if date is in the past (corrected to handle today issue)
function notPastDate(date, fieldName, controlMessage, validationMessage, exclude) {
	if (exclude) {
		if (date != null && date <= new Date()) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	} else {
		var today = new Date();
		today.setHours(0, 0, 0, 0);
		//		alert("today = "+today);
		//		alert("date = "+ date);
		if (date != null && date < today) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	}
}
