tw.local.customerAndPartyCifs = [];
var customerCIF = tw.local.odcRequest.CustomerInfo.cif;

// accountee is removed
//var partyCIF = tw.local.odcRequest.Parties?.partyTypes?.partyId || "";
var caseInNeedCIF = tw.local.odcRequest.Parties?.caseInNeed?.partyId || "";

//Build Cifs list with valid values or "" as default
