//!!partyCIF ? tw.local.customerAndPartyCifs[1] = partyCIF : tw.local.customerAndPartyCifs[1] = "";

!!caseInNeedCIF ? tw.local.customerAndPartyCifs[2] = caseInNeedCIF : tw.local.customerAndPartyCifs[1] = "";

//remove duplicate cifs using SET
tw.local.customerAndPartyCifs = [...new Set(tw.local.customerAndPartyCifs)];

ns16:scriptTask.ns16:script:
tw.local.alertMessage = String(tw.error.data);
tw.local.errorVis = "EDITABLE";


tw.local.errorMessageVis = "editable";
tw.local.errorMessage = String(tw.error.data);

tw.local.odcRequest.isLiquidated = false;

//Init actionConditions "This object used by service (Get Actions by ScreenName 2) "
tw.local.actionConditions={};
tw.local.actionConditions.complianceApproval= false;
tw.local.actionConditions.lastStepAction= tw.local.odcRequest.stepLog.action;
tw.local.actionConditions.screenName= tw.epv.Col_ScreenNames.ODCCol01;
tw.local.actionConditions.userRole= tw.local.odcRequest.initiator;
tw.local.actionConditions.subStatus= tw.local.odcRequest.appInfo.subStatus;	 
tw.local.actionConditions.isLiquidated= tw.local.odcRequest.isLiquidated;	

tw.local.odcRequest.stepLog={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step = tw.epv.Col_ScreenNames.ODCCol01; 

console.log("-----------------111111111111111111111------------------------------------------");

if (tw.local.odcRequest.stepLog.action == tw.epv.Col_Actions.createLiq+"" ){
	tw.local.odcRequest.appInfo.status = tw.epv.Status.InExecution+"";
	tw.local.odcRequest.appInfo.subStatus = tw.epv.subStatus.pendingExHubLiqReview+"";
	
} else if(tw.local.odcRequest.stepLog.action == tw.epv.Col_Actions.cancel+""){
	tw.local.odcRequest.appInfo.status = "" + tw.epv.Status.initiated;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.PendingCancelationConfirmation;
}

tw.local.odcRequest.appInfo.instanceID = tw.local.odcRequest.requestNo; 
tw.local.todayDate = new Date();
tw.local.positionSearch = false;

tw.local.odcRequest.instanceNo = tw.system.processInstance.id;
tw.local.calculateOutstandingAmount = true;
tw.local.odcRequest.initiator = tw.system.user.name;

//tw.local.odcRequest.stepLog={};
//tw.local.odcRequest.stepLog.startTime = new Date();
//tw.local.odcRequest.stepLog.step = tw.epv.Col_ScreenNames.ODCCol01; 
/* Financial Trade Fo CV*/
if(tw.local.odcRequest.BasicDetails.paymentTerms.name == "004")
{
	tw.local.multiTenorVIS = "READONLY";
}
else
{
	tw.local.multiTenorVIS = "NONE";
}
tw.local.collectionContract = false;

ns16:extensionElements.ns2:postAssignmentScript:
console.group("<<CONTRACT LIQUIDATION>>");
console.log("LIQUIDATION REQ");
console.log(tw.local.xmlRequest);
console.log("LIQUIDATION RES");
console.log( tw.local.xmlResponse );
console.log("<<items>>");
console.log(tw.local.messageList);
console.log("<<errorMessage>>");
console.log(tw.local.errorMessageVis);
console.groupEnd();

if(tw.local.isSuccessful == false){
	var msg = "Liquidate BC Contract Integration Failed";
	var items = tw.local.messageList;
	tw.local.errorMessageVis = "editable";
	
	if(items && items.length > 0){
		var listItems = items.map(item => `<li>${item}</li>`).join('');
		tw.local.errorMessage = msg + '<br>' + `<ul>${listItems}</ul>`;
	}
	else if (!!tw.local.errorMessage){
		tw.local.errorMessage = msg + '<br>' + `<ul>${tw.local.errorMsg}</ul>`;
	}else{
		tw.local.errorMessage = msg;	
	}
}
else{
	tw.local.collectionContract = true;
}

